feedbackvariables.text:
/* node 1: check answers correct */
node1_test: if ans1=1992 and ans2="Elamat" and ans3=1869.80 then 1 else 0;

/* node 2: fails to compare the units in each question */
node2_test: if ans1=2013 and ans2="Palstond" and ans3=186.98 then 1 else 0;

/* node 3: treats 2000-16 stations as unknown */
node3_test: if ans1=1992 and member(ans2, ["Palstond", "Unknown"]) and ans3=1869.80 then 1 else 0;

/* node 4: disregards the order of the columns */
node4_test: if ans1=2013 and ans2="Elamat" and member(ans3, [1869.8, 186.98]) then 1 else 0;

/* node 5: disregards the order of the columns */
node5_test: if ans1=1992 and ans2="Palstond" and member(ans3, [17567.7, 175677]) then 1 else 0;
